101	    @Transactional(readOnly = true)
102	    public List<Long> inListOrder(String sheetId, Collection<Long> ids) {
103	        Set<Long> wanted = new HashSet<>(ids);
104	        Map<Long, Integer> personOrder = new HashMap<>();
105	        List<Person> theirs = people.findBySheetIdOrderByIdAsc(sheetId);
106	        for (int i = 0; i < theirs.size(); i++) {
107	            personOrder.put(theirs.get(i).getId(), i);
108	        }
109	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
110	                .filter(c -> wanted.contains(c.getId()))
111	                .sorted(Comparator.comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
112	                .map(Claim::getId)
113	                .toList();
