116	    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. Refused
117	     *  (423) when the date is in a closed period, (422) when it is after the person's
118	     *  retirement date, and (422) when it is a correction (a negative amount) that does not name
119	     *  the number of a SETTLED claim of the same person. */
120	    @Transactional
121	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
122	            String corrects) {
123	        Person person = people.findByIdAndSheetId(personId, sheetId)
124	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
125	        LocalDate on = date != null ? date : sheets.today(sheetId);
126	        refuseIfClosed(sheetId, on);
127	        refuseIfRetired(person, on);
128	        String corrected = correctedBy(sheetId, personId, amount, corrects);
129	        RollupService.Snapshot before = rollup.snapshot(sheetId);
130	        int terms = person.getTerms() != null ? person.getTerms()
131	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
132	        Claim fresh = new Claim(sheetId, personId, amount, on, on.plusDays(terms), noteOf(note));
133	        fresh.setCorrects(corrected);
134	        // the sheet is locked (refuseIfClosed), so two claims added at once are listed one after the other
135	        fresh.setListed(claims.findLastListed(sheetId) + 1);
136	        Claim claim = claims.saveAndFlush(fresh);
137	        logStatus(user, person, claim);
138	        record("CLAIM_ADDED", user, person, claim);
139	        rollup.recordChanges(sheetId, user, before);
140	        return claim;
141	    }
