143	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today.
144	     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
145	     *  added instead), and (423) when its old or new date is in a closed period, and (422) when the new
146	     *  date is after the person's retirement date, or when it is a correction that does not name
147	     *  the number of a SETTLED claim of the same person. */
148	    @Transactional
149	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
150	            String corrects) {
151	        Claim claim = claims.findForUpdate(id, sheetId)
152	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
153	        LocalDate on = date != null ? date : sheets.today(sheetId);
154	        refuseIfClosed(sheetId, claim.getDate());
155	        if (claim.getStatus() != ClaimStatus.DRAFT) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT,
157	                    "A " + claim.getStatus() + " claim cannot be edited");
158	        }
159	        refuseIfClosed(sheetId, on);
160	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
161	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
162	        refuseIfRetired(person, on);
163	        String corrected = correctedBy(sheetId, person.getId(), amount, corrects);
164	        RollupService.Snapshot before = rollup.snapshot(sheetId);
165	        claim.setAmount(amount);
166	        claim.setCorrects(corrected);
167	        claim.setDate(on);
168	        claim.setNote(noteOf(note));
169	        claims.flush();
170	        record("CLAIM_EDITED", user, person, claim);
171	        rollup.recordChanges(sheetId, user, before);
172	        return claim;
173	    }
