175	    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
176	     *  a move the user's role may not make by the sheet's permission matrix (403), settling by the user who opened the claim (403), settling a deferred claim (409), settling a PENDING claim (409: it is
177	     *  approved or rejected instead), voiding a SETTLED claim by anyone but a steward (403) or more
178	     *  than 7 days after its settlement (409), and any move of a claim dated in a closed period (423). A
179	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. Settling
180	     *  a claim whose due is above the proof threshold in force on its date while it has no proof is
181	     *  refused (422) before the clerk limit is considered. */
182	    @Transactional
183	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
184	        Claim claim = claims.findForUpdate(id, sheetId)
185	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
186	        refuseIfClosed(sheetId, claim.getDate());
187	        switch (to) {
188	            case OPEN -> settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
189	            case SETTLED -> settings.refuseUnlessAllowed(sheetId, user, Permission.SETTLE);
190	            case VOID -> settings.refuseUnlessAllowed(sheetId, user, Permission.VOID);
191	            default -> {
192	            }
193	        }
194	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
195	                || !claim.getStatus().canMoveTo(to)) {
196	            throw new ResponseStatusException(HttpStatus.CONFLICT,
197	                    "A " + claim.getStatus() + " claim cannot become " + to);
198	        }
199	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
200	            refuseUnlessVoidableSettled(sheetId, user, claim);
201	        }
202	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
203	            throw new ResponseStatusException(HttpStatus.CONFLICT,
204	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
205	        }
206	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
207	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
208	                    "The user who opened a claim cannot settle it");
209	        }
210	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
211	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
212	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
213	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
214	        if (to == ClaimStatus.SETTLED) {
215	            // before the clerk limit: a claim needing a proof never goes to PENDING
216	            refuseIfUnproven(claim, settling);
217	        }
218	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
219	            // above the clerk limit: a steward approves or rejects it
220	            to = ClaimStatus.PENDING;
221	        }
222	        RollupService.Snapshot before = rollup.snapshot(sheetId);
223	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
224	        String number = claim.getNumber();
225	        // a voided SETTLED claim keeps its frozen figure, which leaves every total
226	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
227	        BigDecimal reversed = claim.getSettledDue();
228	        claim.setStatus(to);
229	        if (to == ClaimStatus.OPEN) {
230	            number = nextNumber(sheetId, claim.getDate());
231	            claim.setNumber(number);
232	            claim.setOpenedBy(user);
233	        } else if (to == ClaimStatus.SETTLED) {
234	            claim.setSettledDue(settling);
235	        }
236	        claims.flush();
237	        logStatus(user, person, claim);
238	        String event = switch (to) {
239	            case OPEN -> "CLAIM_OPENED";
240	            case PENDING -> "CLAIM_PENDING";
241	            case SETTLED -> "CLAIM_SETTLED";
242	            case VOID -> "CLAIM_VOIDED";
243	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
244	        };
245	        if (to == ClaimStatus.SETTLED) {
246	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
247	            notifyWatchers(user, person, number);
248	        } else if (reversing) {
249	            record(event, user, person, claim, number, " reversed=" + dueText(reversed));
250	        } else {
251	            record(event, user, person, claim, number);
252	        }
253	        rollup.recordChanges(sheetId, user, before);
254	        return claim;
255	    }
