257	    /** Refuse voiding a SETTLED claim (403) by anyone but a steward, and (409) once the sheet's
258	     *  today is more than {@link ClaimStatus#SETTLED_VOID_DAYS} days after its settlement (the
259	     *  first SETTLED line of its status log). */
260	    private void refuseUnlessVoidableSettled(String sheetId, String user, Claim claim) {
261	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
262	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim");
263	        }
264	        LocalDate settledOn = log.findByClaimIdOrderByIdAsc(claim.getId()).stream()
265	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
266	                .map(ClaimLog::getOn)
267	                .findFirst()
268	                .orElse(null);
269	        LocalDate today = sheets.today(sheetId);
270	        if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.SETTLED_VOID_DAYS))) {
271	            throw new ResponseStatusException(HttpStatus.CONFLICT,
272	                    "A SETTLED claim is voided only within " + ClaimStatus.SETTLED_VOID_DAYS + " days of its settlement");
273	        }
274	    }
