276	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches
277	     *  it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
278	     *  statement. Refused (404) when missing, (423) when dated in a closed period, (409) unless
279	     *  OPEN, and (422) when the date is not after the sheet's today. */
280	    @Transactional
281	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
282	        Claim claim = claims.findForUpdate(id, sheetId)
283	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
284	        refuseIfClosed(sheetId, claim.getDate());
285	        if (claim.getStatus() != ClaimStatus.OPEN) {
286	            throw new ResponseStatusException(HttpStatus.CONFLICT,
287	                    "Only an OPEN claim is deferred, not a " + claim.getStatus() + " one");
288	        }
289	        if (!until.isAfter(sheets.today(sheetId))) {
290	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
291	                    "A claim is deferred until a date after the sheet's today");
292	        }
293	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
294	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
295	        RollupService.Snapshot before = rollup.snapshot(sheetId);
296	        claim.setDeferredUntil(until);
297	        claims.flush();
298	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), " until=" + until);
299	        rollup.recordChanges(sheetId, user, before);
300	        return claim;
301	    }
