303	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
304	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
305	     *  opened it, (423) when it is dated in a closed period, and (422) when its due is above the
306	     *  proof threshold in force on its date while it has no proof. */
307	    @Transactional
308	    public Claim approve(String sheetId, String user, long id) {
309	        Claim claim = pendingForSteward(sheetId, user, id);
310	        if (user.equals(claim.getOpenedBy())) {
311	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
312	                    "The user who opened a claim cannot approve it");
313	        }
314	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
315	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
316	        BigDecimal due = shownDueOf(claim, person);
317	        refuseIfUnproven(claim, due);
318	        RollupService.Snapshot before = rollup.snapshot(sheetId);
319	        claim.setStatus(ClaimStatus.SETTLED);
320	        claim.setSettledDue(due);
321	        claims.flush();
322	        logStatus(user, person, claim);
323	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
324	        notifyWatchers(user, person, claim.getNumber());
325	        rollup.recordChanges(sheetId, user, before);
326	        return claim;
327	    }
