329	    /** Add a proof to a claim, raising its proofs count by one. Refused (404) when missing, (423)
330	     *  when dated in a closed period, and (409) when SETTLED or VOID. */
331	    @Transactional
332	    public Claim addProof(String sheetId, String user, long id) {
333	        Claim claim = claims.findForUpdate(id, sheetId)
334	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
335	        refuseIfClosed(sheetId, claim.getDate());
336	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
337	            throw new ResponseStatusException(HttpStatus.CONFLICT,
338	                    "A " + claim.getStatus() + " claim takes no more proofs");
339	        }
340	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
341	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
342	        claim.addProof();
343	        claims.flush();
344	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), " proofs=" + claim.getProofs());
345	        return claim;
346	    }
