348	    /** Refuse (422) settling or approving a claim at a due (null: n/a) above the proof threshold in
349	     *  force on its date while it has no proof. */
350	    private void refuseIfUnproven(Claim claim, BigDecimal due) {
351	        if (claim.getProofs() > 0 || due == null) {
352	            return;
353	        }
354	        BigDecimal threshold = sheets.proofThresholdOn(claim.getSheetId(), claim.getDate());
355	        if (threshold != null && due.compareTo(threshold) > 0) {
356	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
357	                    "A claim whose due is above the proof threshold needs a proof first");
358	        }
359	    }
