361	    /** A steward re-settles a SETTLED claim: its due is frozen again at the figure it would show
362	     *  today as an open claim bound by no statement (today's rates, grades, floor and late
363	     *  charge). Refused (404) when missing, (423) when dated in a closed period, (403) for anyone
364	     *  but a steward, and (409) unless SETTLED. */
365	    @Transactional
366	    public Claim resettle(String sheetId, String user, long id) {
367	        Claim claim = claims.findForUpdate(id, sheetId)
368	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
369	        refuseIfClosed(sheetId, claim.getDate());
370	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
371	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
372	        }
373	        if (claim.getStatus() != ClaimStatus.SETTLED) {
374	            throw new ResponseStatusException(HttpStatus.CONFLICT,
375	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
376	        }
377	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
378	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
379	        RollupService.Snapshot before = rollup.snapshot(sheetId);
380	        BigDecimal old = claim.getSettledDue();
381	        BigDecimal due = flooredOf(claim,
382	                LateCharge.of(sheets.find(sheetId)).addToOpen(claim, rateFigureOf(claim, person), roundingOf(claim)));
383	        claim.setSettledDue(due);
384	        claims.flush();
385	        logStatus(user, person, claim);
386	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(),
387	                " old=" + dueText(old) + " new=" + dueText(due));
388	        notifyWatchers(user, person, claim.getNumber());
389	        rollup.recordChanges(sheetId, user, before);
390	        return claim;
391	    }
