393	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
394	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
395	     *  a clerk, and (423) when it is dated in a closed period. */
396	    @Transactional
397	    public Claim reject(String sheetId, String user, long id, String reason) {
398	        Claim claim = pendingForSteward(sheetId, user, id);
399	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
400	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
401	        RollupService.Snapshot before = rollup.snapshot(sheetId);
402	        claim.setStatus(ClaimStatus.OPEN);
403	        claims.flush();
404	        logStatus(user, person, claim);
405	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
406	        rollup.recordChanges(sheetId, user, before);
407	        return claim;
408	    }
