410	    /** A steward (or a role the permission matrix lets reassign) moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
411	     *  number and date, is listed as the new person's newest claim, and loses any figure a
412	     *  statement bound it to (live again until the new person's next statement). Refused (404)
413	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
414	     *  role the sheet's permission matrix does not let reassign, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
415	     *  the new person's retirement date. */
416	    @Transactional
417	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
418	        Claim claim = claims.findForUpdate(id, sheetId)
419	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
420	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
421	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
422	        refuseIfClosed(sheetId, claim.getDate());
423	        settings.refuseUnlessAllowed(sheetId, user, Permission.REASSIGN);
424	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
425	            throw new ResponseStatusException(HttpStatus.CONFLICT,
426	                    "A " + claim.getStatus() + " claim cannot be reassigned");
427	        }
428	        if (claim.getPersonId() == toPersonId) {
429	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
430	        }
431	        refuseIfRetired(to, claim.getDate());
432	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
433	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
434	        RollupService.Snapshot before = rollup.snapshot(sheetId);
435	        claim.setPersonId(to.getId());
436	        claim.unbind();
437	        claim.setListed(claims.findLastListed(sheetId) + 1);
438	        claims.flush();
439	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
440	                " from=" + from.getName() + " to=" + to.getName());
441	        rollup.recordChanges(sheetId, user, before);
442	        return claim;
443	    }
