445	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any
446	     *  figure a statement bound it to, and a new OPEN claim of the amount, with the same date and
447	     *  note, the next number, opened by the user, its due-by fixed now from the terms in force on
448	     *  the date (the person's own, else their grade's, else the sheet's), and naming the original's number as split-from, is listed as the person's newest.
449	     *  Refused (404) when missing, (423) when dated in a closed period, (403) for a role the
450	     *  sheet's permission matrix does not let open a claim, (409) unless OPEN and not deferred on
451	     *  the sheet's today, and (422) unless the amount is more than 0.00 and less than the claim's. */
452	    @Transactional
453	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
454	        Claim claim = claims.findForUpdate(id, sheetId)
455	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
456	        refuseIfClosed(sheetId, claim.getDate());
457	        settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
458	        if (claim.getStatus() != ClaimStatus.OPEN) {
459	            throw new ResponseStatusException(HttpStatus.CONFLICT,
460	                    "Only an OPEN claim is split, not a " + claim.getStatus() + " one");
461	        }
462	        if (claim.isDeferredOn(sheets.today(sheetId))) {
463	            throw new ResponseStatusException(HttpStatus.CONFLICT,
464	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then");
465	        }
466	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
467	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
468	                    "The amount split off must be more than 0.00 and less than the claim's");
469	        }
470	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
471	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
472	        RollupService.Snapshot before = rollup.snapshot(sheetId);
473	        LocalDate on = claim.getDate();
474	        claim.setAmount(claim.getAmount().subtract(amount));
475	        claim.unbind();
476	        int terms = person.getTerms() != null ? person.getTerms()
477	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
478	        Claim fresh = new Claim(sheetId, person.getId(), amount, on, on.plusDays(terms), claim.getNote());
479	        fresh.setStatus(ClaimStatus.OPEN);
480	        fresh.setNumber(nextNumber(sheetId, on));
481	        fresh.setOpenedBy(user);
482	        fresh.setSplitFrom(claim.getNumber());
483	        fresh.setListed(claims.findLastListed(sheetId) + 1);
484	        Claim split = claims.saveAndFlush(fresh);
485	        logStatus(user, person, split);
486	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), " into=" + split.getNumber());
487	        record("CLAIM_OPENED", user, person, split);
488	        rollup.recordChanges(sheetId, user, before);
489	        return new Split(claim, split);
490	    }
491	
492	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
493	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
494	    private Claim pendingForSteward(String sheetId, String user, long id) {
495	        Claim claim = claims.findForUpdate(id, sheetId)
496	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
497	        refuseIfClosed(sheetId, claim.getDate());
498	        if (claim.getStatus() != ClaimStatus.PENDING) {
499	            throw new ResponseStatusException(HttpStatus.CONFLICT,
500	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
501	        }
502	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
503	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
504	                    "Only a steward approves or rejects a PENDING claim");
505	        }
506	        return claim;
507	    }
508	
509	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
510	     *  it shows at this moment. */
511	    private void logStatus(String user, Person person, Claim claim) {
512	        BigDecimal due = shownDueOf(claim, person);
513	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
514	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
515	    }
516	
517	    private static String dueText(BigDecimal due) {
518	        return due == null ? "n/a" : due.toPlainString();
519	    }
520	
521	    /** Take a statement of a person: record their due-total now, and bind each of their claims
522	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
523	     *  are left unbound. */
524	    @Transactional
525	    public Statement statement(String sheetId, String user, long personId) {
526	        Person person = people.findForUpdate(personId, sheetId)
527	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
528	        LocalDate today = sheets.today(sheetId);
529	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
530	        RollupService.Snapshot before = rollup.snapshot(sheetId);
531	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
532	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
533	        for (Claim c : theirs) {
534	            if (counts(c, person, today)) {
535	                // the statement binds the figure; the late charge keeps following the sheet's today
536	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
537	            } else {
538	                c.unbind();
539	            }
540	        }
541	        claims.flush();
542	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
543	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
544	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
545	        rollup.recordChanges(sheetId, user, before);
546	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
547	    }
548	
549	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
550	     *  and the sheet's today on or after it) the next within the period containing the date
551	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
552	    private String nextNumber(String sheetId, LocalDate date) {
553	        if (!sheets.periodNumberingOn(sheetId)) {
554	            return String.valueOf(sheets.nextClaimNumber(sheetId));
555	        }
556	        // held until the transaction ends, so two claims opened at once are numbered one after the other
557	        sheets.lock(sheetId);
558	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
559	        int last = claims.findNumbers(sheetId).stream()
560	                .filter(n -> n.startsWith(prefix))
561	                .map(n -> n.substring(prefix.length()))
562	                .filter(n -> n.matches("\\d{1,9}"))
563	                .mapToInt(Integer::parseInt)
564	                .max().orElse(0);
565	        return prefix + (last + 1);
566	    }
567	
568	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
569	     *  the transaction ends so a period cannot be closed meanwhile. */
570	    private void refuseIfClosed(String sheetId, LocalDate date) {
571	        sheets.lock(sheetId);
572	        periods.refuseIfClosed(sheetId, date);
573	    }
574	
575	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
576	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
577	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
578	        if (amount.signum() >= 0) {
579	            return null;
580	        }
581	        if (corrects == null
582	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
583	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
584	                    "A negative amount must correct a settled claim of the same person");
585	        }
586	        return corrects;
587	    }
588	
589	    /** Refuse (422) a claim dated after its person's retirement date. */
590	    private static void refuseIfRetired(Person person, LocalDate date) {
591	        if (person.retiredBefore(date)) {
592	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
593	                    "The date is after the person's retirement date");
594	        }
595	    }
596	
597	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
598	     *  do, but not an open one dated within a hold of its person unless bound by a statement, nor
599	     *  one deferred on the sheet's today. */
600	    private static boolean counts(Claim c, Person person, LocalDate today) {
601	        return c.getStatus() == ClaimStatus.SETTLED
602	                || (c.getStatus().isOpen() && !c.isDeferredOn(today) && (c.isBound() || !person.heldOn(c.getDate())));
603	    }
604	
605	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
606	     *  charge on top, raised to the floor in force on its date. */
607	    private BigDecimal shownDueOf(Claim claim, Person person) {
608	        if (claim.getSettledDue() != null) {
609	            return claim.getSettledDue();
610	        }
611	        return flooredOf(claim,
612	                LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim)));
613	    }
614	
615	    /** A due (null: n/a, which stays n/a) raised to the sheet's floor in force on the claim's date; a
616	     *  correction's never is. */
617	    private BigDecimal flooredOf(Claim claim, BigDecimal due) {
618	        if (due == null || claim.isCorrection()) {
619	            return due;
620	        }
621	        return due.max(sheets.floorOn(claim.getSheetId(), claim.getDate()));
622	    }
623	
624	    /** A claim's figure before any late charge or floor: the one a statement bound it to (null: n/a),
625	     *  else (unbound, or PENDING) its rate figure. */
626	    private BigDecimal figureOf(Claim claim, Person person) {
627	        return claim.isBound() ? claim.getStatedDue() : rateFigureOf(claim, person);
628	    }
629	
630	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
631	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
632	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
633	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
634	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
635	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
636	            return null;
637	        }
638	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
639	    }
640	
641	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
642	     *  100, rounded as its rounding policy has it; null with no rate in force then. */
643	    private BigDecimal rateFigureOf(Claim claim, Person person) {
644	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
645	                .map(Rate::getPct)
646	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
647	                .orElse(null);
648	    }
649	
650	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
651	     *  correction the date of the claim it corrects. */
652	    private RoundingMode roundingOf(Claim claim) {
653	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
654	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
655	                        .map(Claim::getDate).orElse(claim.getDate());
656	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
657	    }
658	
659	    private void record(String event, String user, Person person, Claim claim) {
660	        record(event, user, person, claim, claim.getNumber());
661	    }
662	
663	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
664	    private void record(String event, String user, Person person, Claim claim, String number) {
665	        record(event, user, person, claim, number, "");
666	    }
667	
668	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
669	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
670	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
671	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
672	    }
673	
674	    /** Notify each user watching the person that one of their claims was settled, in the order
675	     *  they started watching. */
676	    private void notifyWatchers(String user, Person person, String number) {
677	        for (PersonWatch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
678	            audit.recordOnCommit("NOTIFY sheet=" + person.getSheetId() + " by=" + user + " user=" + w.getUserName()
679	                    + " person=" + person.getName() + " number=" + number);
680	        }
681	    }
682	
683	    private static String noteOf(String note) {
684	        return note == null ? "" : note.trim();
685	    }
686	}
